  "title": "A designer with a fresh context reviews the rendered pages of every pull request that touches pages, against the approved prototype when there is one",
  "public_title": "Add a designer review of rendered pages to pull requests",
  "scope": [
    "bin/**",
    "skills/designer/**",
    "skills/firstmate/SKILL.md",
    "skills/reviewer/SKILL.md",
    "skills/firstmate/rule-inventory.json",
